/* ==========================================================================
   WING MASTER — TUYAUX THÉMATIQUES  (9 ligues, images intégrées ~1.3 Mo)
   --------------------------------------------------------------------------
   INTÉGRATION — colle ce fichier avant ton code de jeu (ou <script src>),
   puis dans ton dessin de tuyaux :

     if (!PipeSkins.draw(ctx, ligue, p.x, PIPE_W, hautTrou, basTrou, SOL_Y)) {
       ancienDessinTuyau(p);   // secours pendant le chargement
     }

     ligue    : index 0..8 de la ligue en cours
     p.x      : bord gauche de la HITBOX du tuyau
     PIPE_W   : largeur logique (hitbox) du fût
     hautTrou : y du BAS du tuyau du haut   (début du trou)
     basTrou  : y du HAUT du tuyau du bas   (fin du trou)
     SOL_Y    : y du sol (optionnel, défaut = ctx.canvas.height ;
                si ton ctx est scalé DPR, passe-le explicitement)

   • Le fût est calé exactement sur [x, x+PIPE_W] : le décor (cristaux,
     lanternes, roses…) dépasse visuellement SANS compter en collision.
   • Rendu 3 tranches : embouchure + zone des emblèmes jamais déformées,
     seule la zone éloignée du trou s'étire pour atteindre le bord d'écran.
   • ORDRE DES LIGUES : ajuste LEAGUE_SKINS ci-dessous.
   ========================================================================== */
(function (global) {
'use strict';

/* Ordre des skins par ligue (index 0 = ligue 1) — À AJUSTER selon ton jeu.
   Clés : foret, glace, ocean, usine, chateau, temple, deco, cristal, fuji */
var LEAGUE_SKINS = ['foret','glace','ocean','usine','chateau','temple','deco','cristal','fuji'];

var MOUTH = 0.38, MID = 0.34;                       /* tranches non étirées */
var QS = Math.min(global.devicePixelRatio || 1, 2); /* netteté rétina       */

var SKINS = {"glace":{"top":{"r":1.2476,"c":0.5013,"b64":"data:image/webp;base64,"},"bottom":{"r":1.2212,"c":0.5013,"b64":"data:image/webp;base64,"}},"fuji":{"top":{"r":1.2178,"c":0.4818,"b64":"data:image/webp;base64,"},"bottom":{"r":1.3155,"c":0.5132,"b64":"data:image/webp;base64,"}},"usine":{"top":{"r":1.2367,"c":0.5029,"b64":"data:image/webp;base64,"},"bottom":{"r":1.3134,"c":0.4987,"b64":"data:image/webp;base64,"}},"foret":{"top":{"r":1.3194,"c":0.5043,"b64":"data:image/webp;base64,"},"bottom":{"r":1.2862,"c":0.4986,"b64":"data:image/webp;base64,"}},"temple":{"top":{"r":1.2493,"c":0.4947,"b64":"data:image/webp;base64,"},"bottom":{"r":1.2885,"c":0.4717,"b64":"data:image/webp;base64,"}},"ocean":{"top":{"r":1.2431,"c":0.511,"b64":"data:image/webp;base64,"},"bottom":{"r":1.2451,"c":0.5031,"b64":"data:image/webp;base64,"}},"chateau":{"top":{"r":1.2644,"c":0.492,"b64":"data:image/webp;base64,"},"bottom":{"r":1.3084,"c":0.5081,"b64":"data:image/webp;base64,"}},"deco":{"top":{"r":1.3174,"c":0.5052,"b64":"data:image/webp;base64,"},"bottom":{"r":1.3219,"c":0.5013,"b64":"data:image/webp;base64,"}},"cristal":{"top":{"r":1.1982,"c":0.4987,"b64":"data:image/webp;base64,"},"bottom":{"r":1.2065,"c":0.492,"b64":"data:image/webp;base64,"}}};

/* -- décodage ----------------------------------------------------------- */
var pending = 0;
Object.keys(SKINS).forEach(function (k) {
  ['top', 'bottom'].forEach(function (s) {
    var o = SKINS[k][s], img = new Image();
    pending++;
    img.onload  = function () { o.img = img; pending--; };
    img.onerror = function () { pending--; };
    img.src = o.b64;
    o.b64 = null;
  });
});

/* -- cache de pré-mise à l'échelle (1 canvas par skin/côté/largeur) ------ */
function place(o, x, w) {
  if (!o.img) return null;
  var pw = w * o.r;                                 /* largeur dessinée     */
  var cw = Math.max(2, Math.round(pw * QS));
  if (!o.cv || o.cv.width !== cw) {
    var ch = Math.max(2, Math.round(cw * o.img.height / o.img.width));
    var cv = document.createElement('canvas');
    cv.width = cw; cv.height = ch;
    cv.getContext('2d').drawImage(o.img, 0, 0, cw, ch);
    o.cv = cv;
  }
  return { cv: o.cv, pw: pw, ph: o.cv.height / QS, ox: x + w / 2 - o.c * pw };
}

function cuts(ph, needed) {
  var mS = ph * MOUTH, midS = ph * MID, farS = ph - mS - midS;
  var mD = Math.min(mS, needed), rem = needed - mD;
  var midD = Math.min(midS, rem); rem -= midD;
  return { mS: mS, midS: midS, farS: farS, mD: mD, midD: midD, farD: rem };
}

/* tuyau du HAUT : embouchure en bas de l'image, collée à hautTrou */
function drawTop(ctx, o, x, w, gapY) {
  if (gapY <= 0) return;
  var p = place(o, x, w); if (!p) return;
  var c = cuts(p.ph, gapY), cw = p.cv.width;
  if (c.farD > 0) ctx.drawImage(p.cv, 0, 0, cw, c.farS * QS, p.ox, 0, p.pw, c.farD);
  if (c.midD > 0) ctx.drawImage(p.cv, 0, c.farS * QS, cw, c.midS * QS, p.ox, c.farD, p.pw, c.midD);
  if (c.mD   > 0) ctx.drawImage(p.cv, 0, (c.farS + c.midS) * QS, cw, c.mS * QS, p.ox, c.farD + c.midD, p.pw, c.mD);
}

/* tuyau du BAS : embouchure en haut de l'image, collée à basTrou */
function drawBottom(ctx, o, x, w, y, groundY) {
  var need = groundY - y;
  if (need <= 0) return;
  var p = place(o, x, w); if (!p) return;
  var c = cuts(p.ph, need), cw = p.cv.width;
  if (c.mD   > 0) ctx.drawImage(p.cv, 0, 0, cw, c.mS * QS, p.ox, y, p.pw, c.mD);
  if (c.midD > 0) ctx.drawImage(p.cv, 0, c.mS * QS, cw, c.midS * QS, p.ox, y + c.mD, p.pw, c.midD);
  if (c.farD > 0) ctx.drawImage(p.cv, 0, (c.mS + c.midS) * QS, cw, c.farS * QS, p.ox, y + c.mD + c.midD, p.pw, c.farD);
}

/* -- API publique -------------------------------------------------------- */
global.PipeSkins = {
  order: LEAGUE_SKINS,
  keys: Object.keys(SKINS),
  loaded: function () { return pending === 0; },
  /* Retourne false tant que le skin n'est pas prêt (garde ton ancien dessin). */
  draw: function (ctx, ligue, x, w, gapTopY, gapBotY, groundY) {
    var n = LEAGUE_SKINS.length;
    var s = SKINS[LEAGUE_SKINS[((ligue % n) + n) % n]];
    if (!s || !s.top.img || !s.bottom.img) return false;
    if (groundY == null) groundY = ctx.canvas.height;
    drawTop(ctx, s.top, x, w, gapTopY);
    drawBottom(ctx, s.bottom, x, w, gapBotY, groundY);
    return true;
  }
};
})(typeof window !== 'undefined' ? window : this);
